before:
    if ((m_mcfg.iIpV6Only != -1) && (family == AF_INET6)) // (not an error if it fails)
    {
        const int res SRT_ATR_UNUSED =
            ::setsockopt(m_iSocket, IPPROTO_IPV6, IPV6_V6ONLY, (const char*)&m_mcfg.iIpV6Only, sizeof m_mcfg.iIpV6Only);
#if ENABLE_LOGGING
        if (res == -1)
        {
            int  err = errno;
            char msg[160];
            LOGC(kmlog.Error,
                 log << "::setsockopt: failed to set IPPROTO_IPV6/IPV6_V6ONLY = " << m_mcfg.iIpV6Only << ": "
                     << SysStrError(err, msg, 159));
        }
#endif // ENABLE_LOGGING
    }

after:
    if ((m_mcfg.iIpV6Only != -1) && (family == AF_INET6))
    {
        if (::setsockopt(m_iSocket, IPPROTO_IPV6, IPV6_V6ONLY,
                        (const char*)&m_mcfg.iIpV6Only, sizeof m_mcfg.iIpV6Only) == -1)
            throw CUDTException(MJ_SETUP, MN_NORES, NET_ERROR);
        int actual = 0;
        socklen_t size = sizeof actual;
        if (::getsockopt(m_iSocket, IPPROTO_IPV6, IPV6_V6ONLY,
                        (char*)&actual, &size) == -1)
            throw CUDTException(MJ_SETUP, MN_NORES, NET_ERROR);
#ifdef _WIN32
        // Winsock may return a one-byte boolean. The zero-filled buffer preserves it.
        if ((size != sizeof actual && size != 1) || (actual != 0) != (m_mcfg.iIpV6Only != 0))
#else
        if (size != sizeof actual || (actual != 0) != (m_mcfg.iIpV6Only != 0))
#endif
            throw CUDTException(MJ_SETUP, MN_NORES, 0);
    }
